import numpy as np
import sys

# Test case 1: negative sizes
try:
    dt = np.dtype('S-1')
    probe('S_minus_1_created', 1)  # Should not reach here
except (TypeError, ValueError, OverflowError) as e:
    probe('S_minus_1_exception', 1)

# Test case 2: U with negative size
try:
    dt = np.dtype('U-1')
    probe('U_minus_1_created', 1)  # Should not reach here
except (TypeError, ValueError, OverflowError) as e:
    probe('U_minus_1_exception', 1)

# Test case 3: V with negative size
try:
    dt = np.dtype('V-1')
    probe('V_minus_1_created', 1)  # Should not reach here
except (TypeError, ValueError, OverflowError) as e:
    probe('V_minus_1_exception', 1)

# Test case 4: non-numeric suffix
try:
    dt = np.dtype('S1234hello')
    probe('S_invalid_suffix_created', 1)  # Should not reach here
except (TypeError, ValueError, OverflowError) as e:
    probe('S_invalid_suffix_exception', 1)

# Test case 5: extremely large size (2**61)
try:
    dt = np.dtype('S' + str(2**61))
    probe('S_2_61_created', 1)  # Should not reach here on fixed
except (TypeError, ValueError, OverflowError) as e:
    probe('S_2_61_exception', 1)

# Test case 6: valid leading zeros
try:
    dt = np.dtype('S010')
    probe('S_010_itemsize', dt.itemsize)
except (TypeError, ValueError, OverflowError) as e:
    probe('S_010_exception', 1)

